import{_ as d,o as e,c as t,ag as c}from"./chunks/framework.CPvOxTBX.js";const h=JSON.parse('{"title":"词典链接 Scheme 原理解析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/dictionary-link-schemes.md","filePath":"zh/guide/dictionary-link-schemes.md","lastUpdated":1793489580000}'),r={name:"zh/guide/dictionary-link-schemes.md"};function a(n,o,l,s,i,g){return e(),t("div",null,o[0]||(o[0]=[c('<h1 id="词典链接-scheme-原理解析" tabindex="-1">词典链接 Scheme 原理解析 <a class="header-anchor" href="#词典链接-scheme-原理解析" aria-label="Permalink to &quot;词典链接 Scheme 原理解析&quot;">​</a></h1><p>词悦支持 MDict、Babylon 与 GoldenDict 词典既有的链接约定。<a href="./dictionary-links.html">词条内链接</a> 一页列出了你可以<em>书写</em>的写法；本页解释这些规则<em>为什么</em>如此——通过剖析 GoldenDict-ng、MDict 与 Babylon 实际如何处理它们、词悦在何处更进一步，以及 一个兼容的阅读器<strong>必须</strong>（和<strong>不必</strong>）支持什么。</p><h2 id="两层-scheme" tabindex="-1">两层 scheme <a class="header-anchor" href="#两层-scheme" aria-label="Permalink to &quot;两层 scheme&quot;">​</a></h2><p>这个生态里的每个链接 scheme 都属于以下两层之一。</p><p><strong>写进词典文件里的</strong>（词典制作者真正写下的）：</p><table tabindex="0"><thead><tr><th>Scheme</th><th>来源</th><th>含义</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>MDX / MDict</td><td>跳转到词条 <code>word</code></td></tr><tr><td><code>bword://word</code></td><td>Babylon <code>.bgl</code></td><td>与 <code>entry://word</code> 相同</td></tr><tr><td><code>gdlookup://localhost/word</code></td><td>GoldenDict-ng</td><td>跨词典查词 <code>word</code></td></tr><tr><td><code>sound://file</code></td><td>MDX / Babylon</td><td>播放音频 <code>file</code></td></tr></tbody></table><p><strong>由 GoldenDict-ng 加载器在运行时生成的</strong>（绝不会出现在源文件中）： <code>gdau</code>、<code>bres</code>、<code>gico</code>、<code>gdprg</code>、<code>gdtts</code>、<code>gdinternal</code>。</p><p>GoldenDict-ng 把 <code>bword</code>、<code>entry</code>（以及 <code>gdlookup</code>）都注册为自定义 URL scheme 并一视同仁：提取词头后在所有已加载词典中查词（<code>main.cc</code> 注册这些 scheme，<code>utils.hh</code> 对 <code>bword</code>/<code>entry</code>/<code>gdlookup</code> 用同一套逻辑解析）。这正是 单个阅读器能同时兼容两种拼写的缘故。</p><h3 id="跨格式混用只在-goldendict-ng-里生效" tabindex="-1">跨格式混用只在 GoldenDict-ng 里生效 <a class="header-anchor" href="#跨格式混用只在-goldendict-ng-里生效" aria-label="Permalink to &quot;跨格式混用只在 GoldenDict-ng 里生效&quot;">​</a></h3><p>由于每个加载器只改写<em>自己</em>的 scheme，你可以造出只有 GoldenDict-ng 才懂的 混合体：</p><ul><li><strong>含 <code>bword://word</code> 的 MDX</strong>：MDX 加载器的链接改写只认 <code>entry://</code> 和 <code>sound://</code>，于是 <code>bword://</code> 原样保留，最终由全局 <code>bword</code> scheme 处理器接住。 原版 MDict 不认 <code>bword:</code>，无法跳转。</li><li><strong>含 <code>entry://word</code> 的 Babylon <code>.bgl</code></strong>：BGL 加载器只规范化 <code>bword:</code>， <code>entry://</code> 因而原样保留、交给全局处理器。原版 Babylon 不懂 <code>entry://</code>。</li></ul><p>即便是&quot;标准&quot;拼写，行为也不同：GoldenDict-ng 把 <code>entry://word</code> 改写成 <code>gdlookup://localhost/word</code>——一次<strong>跨所有</strong>已加载词典的查词；而 MDict 自己的 <code>entry://</code> 只在<strong>当前 <code>.mdx</code> 内部</strong>跳转。</p><h2 id="sound-与-stardict-转换陷阱" tabindex="-1"><code>sound://</code> 与 StarDict 转换陷阱 <a class="header-anchor" href="#sound-与-stardict-转换陷阱" aria-label="Permalink to &quot;`sound://` 与 StarDict 转换陷阱&quot;">​</a></h2><p><code>sound://</code> 是 MDX/Babylon 的音频约定。在 GoldenDict-ng 里<strong>只有 MDX 加载器</strong> 会把 <code>sound://</code> 改写成 <code>gdau://</code>（其内部的音频 scheme）。StarDict 加载器<strong>不会</strong> 改写 <code>sound://</code>：它的链接改写对带有 <code>:</code> 的 <code>a</code> 链接原样放过，而它的 <code>&lt;audio&gt;</code> 处理器只转换<strong>不含</strong> <code>://</code> 的 src。由于 <code>sound</code> 并未注册为 scheme，一个残留在 StarDict 文件里的 <code>sound://</code> 链接就是死链。</p><p>这正是&quot;把 MDX 转成 StarDict 后 <code>sound://</code> 用不了&quot;的原因：音频标签不再被改写。 相反，<code>&lt;audio src=&quot;relative.wav&quot;&gt;</code>（无 <code>://</code>）在 StarDict 加载器里<strong>能</strong>用， 因为它会被改写成 <code>gdau://</code>。</p><p>实践建议：</p><ul><li>若词典带有 MDX 音频，直接加载原始 MDX 即可，原生支持、<code>sound://</code> 处理无误。</li><li>若必须产出 StarDict，让转换工具输出 StarDict 原生的相对资源（相对路径的 <code>&lt;audio&gt;</code> src，或 <code>snd:</code> 资源形式），而不是 MDX 风格的 <code>sound://</code> 链接。</li></ul><h2 id="gdlookup-localhost-word-——-稳定的跨词典引用" tabindex="-1"><code>gdlookup://localhost/word</code> —— 稳定的跨词典引用 <a class="header-anchor" href="#gdlookup-localhost-word-——-稳定的跨词典引用" aria-label="Permalink to &quot;`gdlookup://localhost/word` —— 稳定的跨词典引用&quot;">​</a></h2><p>与下面的 <code>gdau://</code> 不同，这种写法是<strong>稳定且可移植</strong>的：</p><ul><li><code>localhost</code> 是 GoldenDict-ng scheme 处理中写死的常量，有意义的部分是路径里 的词头。</li><li>解析时在所有已加载词典中查词，因此移动、重命名、复制词典文件都无所谓。</li><li>它按&quot;内容&quot;寻址而非按&quot;位置&quot;寻址，所以可以手工编写——也确实出现在真实词典中 （包括词悦作者自制的若干程序辞典）。</li></ul><p>词悦支持它：其词条 URL 判定接受 host 为 <code>localhost</code> 的 <code>gdlookup</code>。</p><h3 id="为什么要有-localhost" tabindex="-1">为什么要有 <code>localhost</code>？ <a class="header-anchor" href="#为什么要有-localhost" aria-label="Permalink to &quot;为什么要有 `localhost`？&quot;">​</a></h3><p>GoldenDict 最初的 commit <code>e4e5a969</code>（Konstantin Isakov，GoldenDict 作者）说得很直白：</p><blockquote><p>Switch to <code>gdlookup://localhost/word</code> scheme in dsl word references. This fixes cases with uppercased/capitalized words. （改用 <code>gdlookup://localhost/word</code>，修复大写/首字母大写词条的跳转。）</p></blockquote><p>URL 的 <strong>host 会被解析器强制转小写</strong>，而 <strong>path 不会</strong>。<code>gdlookup://Word</code> 到达解析层就变成 <code>word</code>，大小写敏感的查词就此失效。那个假的 authority <code>localhost</code> 存在只有一个目的：把词头推进<strong>路径</strong>，让大小写得以保留。</p><p>词悦撞上了同一个 bug，并用同一种方式修复。早期词悦把词头放在 host 里，于是 <code>entry://Abend</code> 到达 Dart 时成了 <code>abend</code>，而 <code>entry://A.D.</code> / <code>entry://tag:sumeru</code> 被当成 <code>host:port</code> 解析、毫无结果（<code>tag:sumeru</code> 里的 <code>:</code> 被当成端口分隔符—— 这个坑最初是在做原神辞典、用到 <code>entry://tag:sumeru</code> 这类链接时踩到的）。修复 把词移进路径，写成 <code>gdlookup://localhost/&lt;百分号编码&gt;</code>，与 GoldenDict 的形态 完全一致、理由也完全相同。这些例子如今已是词悦里常驻的回归测试。</p><h2 id="gdau-——-为什么兼容阅读器可以无视它" tabindex="-1"><code>gdau://</code> —— 为什么兼容阅读器可以无视它 <a class="header-anchor" href="#gdau-——-为什么兼容阅读器可以无视它" aria-label="Permalink to &quot;`gdau://` —— 为什么兼容阅读器可以无视它&quot;">​</a></h2><p><code>gdau://&lt;id&gt;/file</code> 看似与 <code>gdlookup://</code> 相似，本质却不同：</p><ul><li><code>&lt;id&gt;</code> 是词典<strong>绝对文件路径的 MD5</strong>（GoldenDict-ng 的 <code>makeDictionaryId</code>）。 文件移动或换机器，它就会变。</li><li><code>&lt;file&gt;</code> 是该词典内的资源名。</li><li>解析时<strong>先按这个 id 哈希定位词典</strong>，再取资源。</li></ul><p>因为 id 是路径派生出的哈希，<code>gdau://</code> <strong>不可移植、也无法手工编写</strong>——你写不出 一个在任何地方都好使的 <code>gdau://</code> 链接。而且它只会被 GoldenDict-ng 的加载器在 <strong>运行时现生成</strong>（MDX 把 <code>sound://</code> 改写成 <code>gdau://</code>；StarDict 把 <code>&lt;audio src=&quot;rel&quot;&gt;</code> 改写成 <code>gdau://</code>）。任何源词典文件里都不含 <code>gdau://</code>。</p><p>所以，一个想做 GoldenDict-ng 超集的第三方阅读器，应当支持<em>作者层</em>的约定 （<code>entry</code>、<code>bword</code>、<code>gdlookup://localhost/…</code>、<code>sound://</code>），而<strong>无需、也不该 指望收到</strong> <code>gdau://</code>。词悦用的是自己的音频管线（<code>sound://</code> 加一个本地 HTTP 服务，提供词典的 <code>res/</code> 与 <code>.mdd</code> 资源）。</p><h2 id="的处理-词悦是严格超集之处" tabindex="-1"><code>#</code> 的处理：词悦是严格超集之处 <a class="header-anchor" href="#的处理-词悦是严格超集之处" aria-label="Permalink to &quot;`#` 的处理：词悦是严格超集之处&quot;">​</a></h2><p>对<strong>锚点</strong>（滚动定位）这部分，GoldenDict-ng 与词悦是等价的：两者都把它作为 <code>?gdanchor=</code> 查询参数而非 <code>#</code> 片段，正是为了避免 <code>#</code> 在到达处理器之前被当成 同文档片段吞掉。</p><p>差别出现在<strong>特殊字符出现在词头本身</strong>时：</p><ul><li>GoldenDict-ng 把词头<strong>裸</strong>塞进路径（<code>gdlookup://localhost/&lt;word&gt;</code>）。词里若含 <code>#</code>（或 <code>?</code>、<code>/</code>），就会变成片段/查询/路径分隔符而截断词；其 <code>gdlookup</code> + 片段分支进而退化成脆弱的 <code>window.location = url</code>。</li><li>词悦对词头<strong>逐字节百分号编码</strong>，于是 <code>#</code> → <code>%23</code>、<code>/</code> → <code>%2F</code>、 <code>?</code> → <code>%3F</code> 永远不会与 URL 语法碰撞，词完整往返（测试 <code>a%2Fb</code> → <code>a/b</code>、 <code>%74%61%67%3A…</code> → <code>tag:sumeru</code> 均为证）。词悦还会兜底救援&quot;页面脚本没改写、 导致 <code>#</code> 残留在片段里&quot;的情况。</li></ul><p>所以在&quot;标识符内含特殊字符&quot;这一轴上，词悦 ⊃ GoldenDict-ng。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scheme</th><th>写进词典?</th><th>稳定/可移植?</th><th>GD-ng</th><th>词悦</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>是（MDX）</td><td>是</td><td>是</td><td>是</td></tr><tr><td><code>bword://word</code></td><td>是（Babylon）</td><td>是</td><td>是</td><td>是</td></tr><tr><td><code>gdlookup://localhost/word</code></td><td>是（可手写）</td><td>是（内容寻址）</td><td>是</td><td>是</td></tr><tr><td><code>sound://file</code></td><td>是（MDX/Babylon）</td><td>是</td><td>MDX 加载器改写→<code>gdau</code></td><td>是（+本地服务）</td></tr><tr><td><code>&lt;audio src=&quot;rel&quot;&gt;</code></td><td>是</td><td>是</td><td>StarDict 加载器→<code>gdau</code></td><td>是</td></tr><tr><td><code>gdau://&lt;id&gt;/file</code></td><td>否（仅运行时）</td><td>否（路径 MD5 id）</td><td>是（内部）</td><td>否（自有音频机制）</td></tr><tr><td><code>bres</code>/<code>gico</code>/<code>gdprg</code>/<code>gdtts</code>/<code>gdinternal</code></td><td>否（仅运行时）</td><td>否</td><td>是（内部）</td><td>否（自有资源机制）</td></tr></tbody></table><p><strong>结论。</strong> 要在<em>词典加载</em>层成为 GoldenDict-ng 的真正超集，就去支持那些事实 标准的&quot;作者层&quot;约定——<code>entry</code>、<code>bword</code>、<code>gdlookup://localhost/…</code> 和 <code>sound://</code>。<code>gdau</code>、<code>bres</code>、<code>gico</code>、<code>gdprg</code>、<code>gdtts</code>、<code>gdinternal</code> 这些 GD 内部 scheme 是运行时产物；用你自己的资源机制替代它们，而不是去解析它们。</p>',39)]))}const p=d(r,[["render",a]]);export{h as __pageData,p as default};
